inline std::string joint_source_membership_fingerprint(const eventio::Json&doc){std::string value="rinkfit.joint_active_source_watch.v1|"+std::to_string(doc.value("row_count",std::size_t(0)));for(const char*key:{"uv","native_pts","shot_index","kind","material_index","admission","fit_role"}){value+="|"+std::string(key)+"=";value+=doc.contains("arrays")&&doc.at("arrays").contains(key)?doc.at("arrays").at(key).value("sha256",std::string("missing")):"missing";}for(const auto&r:doc.value("source_manifests",eventio::Json::array()))value+="|source_manifest="+r.value("sha256",std::string("missing"));return eventio::sha256(std::vector<std::uint8_t>(value.begin(),value.end()));}
inline eventio::Json joint_source_guard_snapshot(const eventio::Json&doc){eventio::Json out={{"row_count",doc.value("row_count",std::size_t(0))},{"arrays",eventio::Json::object()},{"source_manifests",eventio::Json::array()},{"source_identity_watchlist",doc.value("source_identity_watchlist",eventio::Json::array())}};for(const char*key:{"uv","native_pts","shot_index","kind","material_index","admission","fit_role"})if(doc.contains("arrays")&&doc.at("arrays").contains(key))out["arrays"][key]={{"sha256",doc.at("arrays").at(key).value("sha256",std::string("missing"))}};for(const auto&ref:doc.value("source_manifests",eventio::Json::array()))out["source_manifests"].push_back({{"sha256",ref.value("sha256",std::string("missing"))}});if(doc.contains("board_material_source_qualification"))out["board_material_source_qualification"]=doc.at("board_material_source_qualification");if(joint_source_membership_fingerprint(out)!=joint_source_membership_fingerprint(doc))throw std::runtime_error("compact source recall guard changed membership fingerprint");return out;}
inline std::filesystem::path joint_source_recall_marker(const eventio::Json&doc,const std::filesystem::path&packet,bool verify_dependencies=false){std::vector<std::filesystem::path>paths={packet};const auto fingerprint=joint_source_membership_fingerprint(doc);for(const auto&r:doc.value("source_identity_watchlist",eventio::Json::array()))if(r.value("source_membership_fingerprint",std::string{})==fingerprint){const std::filesystem::path q=r.at("file").get<std::string>();if(verify_dependencies&&eventio::file_sha256(q)!=r.at("sha256").get<std::string>())throw std::runtime_error("changed same-source qualification dependency "+q.string());paths.push_back(q);}if(doc.contains("board_material_source_qualification")){auto ref=doc.at("board_material_source_qualification");auto q=std::filesystem::path(ref.contains("file")?ref.at("file").get<std::string>():ref.at("path").get<std::string>());if(!q.is_absolute())q=packet.parent_path()/q;if(verify_dependencies)eventio::verify(q,ref.at("sha256").get<std::string>());paths.push_back(q);}for(const auto&q:paths)for(const char*name:{"SOURCE_IDENTITY_CERTIFICATE_RECALLED.json","SOURCE_IDENTITY_EVIDENCE_RECALL.json"}){const auto marker=q.parent_path()/name;if(std::filesystem::exists(marker))return marker;}return {};}
inline bool joint_recalled_board_source_id(const std::string&s){for(const char*p:{"board_instance_native/","board_instance/","outer_native/"})if(s.rfind(p,0)==0)return true;return false;}
inline std::filesystem::path joint_qualification_ref(const eventio::Json&ref,const std::filesystem::path&base){const auto file=ref.contains("file")?ref.at("file").get<std::string>():ref.at("path").get<std::string>();auto path=std::filesystem::path(file);if(!path.is_absolute())path=base/path;path=JointExactDependencyAliasesV1::resolve(path,ref.at("sha256").get<std::string>());eventio::verify(path,ref.at("sha256").get<std::string>());return path;}
inline std::string joint_guard_string_sha(const std::string&s){return eventio::sha256(std::vector<std::uint8_t>(s.begin(),s.end()));}
template<class Packet>inline void assert_joint_reviewed_source_revision(const Packet&,const std::filesystem::path&,const eventio::Json&,const std::filesystem::path&);
template<class Packet>inline void assert_joint_static_ice_prefix(const Packet&,const std::filesystem::path&,const eventio::Json&,const std::filesystem::path&);
