// Current production facade: V6 requires the actual model as well as immutable
// source evidence. The two-argument V1--V5 implementation above stays intact.
namespace rinkfit {
template<class Packet,class Model>inline void assert_joint_static_board_prefix_qualification(const Packet&,const std::filesystem::path&,const Model&);
}
#include "rinkfit/joint_static_board_source_guard.hpp"
#include "rinkfit/joint_known_after_board_source_guard.hpp"
#include "rinkfit/joint_static_board_successor_source_guard.hpp"
#include "rinkfit/joint_curve_source_prefix_guard.hpp"
#include "rinkfit/joint_paint_operator_transition_guard.hpp"
#include "rinkfit/joint_R_inner_source_prefix_guard.hpp"
namespace rinkfit {
template<class Packet,class Model>inline void assert_joint_board_source_qualification(const Packet&p,const std::filesystem::path&packet,const Model&model){
 const auto&doc=p.source_json;
 if(doc.contains("board_material_source_qualification")){
  const auto path=joint_qualification_ref(doc.at("board_material_source_qualification"),packet.parent_path());
  const auto cert=eventio::read_json(path);
  if(cert.value("schema",std::string{})=="rinkfit.actual_R_inner_source_after_bound_V9_prefix.v1")return assert_joint_R_inner_source_prefix(p,packet,model);
  if(cert.value("schema",std::string{})=="rinkfit.actual_source_operator_qualification.v9_original_midpoint_to_pair")return assert_joint_paint_operator_transition(p,packet,model);
  if(cert.value("schema",std::string{})=="rinkfit.native_source_fit_qualification.v8_finite_ice_curve_prefix")return assert_joint_curve_source_prefix_qualification(p,packet,model);
 if(cert.value("schema",std::string{})=="rinkfit.board_material_fit_qualification.v7_static_board_successor_prefix")return assert_joint_static_board_successor_prefix_qualification(p,packet,model);
  if(cert.contains("parent_recursion_contract"))return assert_joint_known_after_board_prefix(p,packet,cert,path,model);
  if(cert.value("schema",std::string{})=="rinkfit.board_material_fit_qualification.v6_static_board_prefix")return assert_joint_static_board_prefix_qualification(p,packet,model);
 }
 assert_joint_board_source_qualification(p,packet);
}
}
